{
  "company": "CRONUS International Ltd.",
  "messageType": "Inventory.PhysInventory.Post",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Inventory.PhysInventory.Post",
    "isEnabled": true,
    "filterTableNo": 233,
    "description": "Bókar línur talningarbókar og skilar vörubókarskrá og númeraröðum færslna.",
    "selectionDescription": "Veldu eina fyrirliggjandi bókarkeyrslu af gerðinni Phys. Inventory sem er ekki ítrekunarbók, með templateName/batchName eða subject TEMPLATE|BATCH eða SystemId. Öll auðkenni verða að vísa á sömu keyrslu.",
    "messageDirection": "Inbound",
    "keywords": [
      "bóka birgðatalningu",
      "bóka talningarbók",
      "færa vörutalningu",
      "bóka talin birgðamagn"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "subject": {
        "use": "optional",
        "forms": [
          "TEMPLATE|BATCH",
          "systemId"
        ],
        "description": "Identifies the journal batch as TEMPLATE|BATCH, or as the SystemId of the Item Journal Batch. Without a subject, send templateName and batchName in data. Every selector that is sent must name the same batch."
      },
      "dataRequired": false,
      "version": "1.0",
      "contentType": "text/json"
    },
    "target": [
      {
        "source": "subject",
        "form": "TEMPLATE|BATCH",
        "description": "The journal template name and the batch name, each at most 10 characters, separated by a vertical bar. The template must be a Phys. Inventory template that is not recurring."
      },
      {
        "source": "subject",
        "form": "guid",
        "description": "The SystemId of the Item Journal Batch."
      },
      {
        "source": "data.templateName, data.batchName",
        "form": "journal template and batch name",
        "description": "The template and the batch together. data.journalTemplateName and data.journalBatchName are accepted as aliases."
      }
    ],
    "parameters": [
      {
        "name": "templateName",
        "type": "string",
        "required": false,
        "description": "Name of an existing Phys. Inventory journal template that is not recurring, at most 10 characters. Send it with batchName unless subject identifies the batch."
      },
      {
        "name": "batchName",
        "type": "string",
        "required": false,
        "description": "Name of an existing journal batch of that template, at most 10 characters. Every selector that is sent must name the same batch."
      },
      {
        "name": "journalTemplateName",
        "type": "string",
        "required": false,
        "description": "Alias of templateName. A value that differs from templateName, ignoring case, is refused."
      },
      {
        "name": "journalBatchName",
        "type": "string",
        "required": false,
        "description": "Alias of batchName. A value that differs from batchName, ignoring case, is refused."
      },
      {
        "name": "lineSystemIds",
        "type": "array",
        "required": false,
        "description": "Nonempty array of distinct SystemIds of journal lines in the selected batch. Only those lines are used. Omit it to use every line of the batch."
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success when the lines were posted."
        },
        {
          "name": "templateName",
          "type": "string",
          "description": "The journal template of the selected batch."
        },
        {
          "name": "batchName",
          "type": "string",
          "description": "The selected journal batch."
        },
        {
          "name": "postedLineCount",
          "type": "integer",
          "description": "Number of lines that were selected and posted."
        },
        {
          "name": "itemRegisterNo",
          "type": "integer",
          "description": "Number of the item register the posting created."
        },
        {
          "name": "fromEntryNo",
          "type": "integer",
          "description": "First item ledger entry number of the register."
        },
        {
          "name": "toEntryNo",
          "type": "integer",
          "description": "Last item ledger entry number of the register."
        },
        {
          "name": "fromPhysInventoryEntryNo",
          "type": "integer",
          "description": "First physical inventory ledger entry number of the register; 0 when the posting created none."
        },
        {
          "name": "toPhysInventoryEntryNo",
          "type": "integer",
          "description": "Last physical inventory ledger entry number of the register; 0 when the posting created none."
        },
        {
          "name": "result",
          "type": "array",
          "description": "The lines that were posted, as they were before posting.",
          "children": [
            {
              "name": "systemId",
              "type": "string",
              "description": "SystemId of the journal line."
            },
            {
              "name": "lineNo",
              "type": "integer",
              "description": "Line number in the batch."
            },
            {
              "name": "itemNo",
              "type": "string",
              "description": "Item number of the line."
            },
            {
              "name": "quantity",
              "type": "decimal",
              "description": "The adjustment quantity of the line."
            },
            {
              "name": "locationCode",
              "type": "string",
              "description": "Location code of the line."
            },
            {
              "name": "newLocationCode",
              "type": "string",
              "description": "New location code of the line."
            },
            {
              "name": "binCode",
              "type": "string",
              "description": "Bin code of the line."
            },
            {
              "name": "newBinCode",
              "type": "string",
              "description": "New bin code of the line."
            },
            {
              "name": "lotNo",
              "type": "string",
              "description": "Lot number; empty when the line has no single tracking assignment."
            },
            {
              "name": "newLotNo",
              "type": "string",
              "description": "New lot number."
            },
            {
              "name": "serialNo",
              "type": "string",
              "description": "Serial number; empty when the line has no single tracking assignment."
            },
            {
              "name": "newSerialNo",
              "type": "string",
              "description": "New serial number."
            },
            {
              "name": "packageNo",
              "type": "string",
              "description": "Package number; empty when the line has no single tracking assignment."
            },
            {
              "name": "newPackageNo",
              "type": "string",
              "description": "New package number."
            },
            {
              "name": "tracking",
              "type": "array",
              "description": "Every item tracking assignment of the line: lotNo, newLotNo, serialNo, newSerialNo, packageNo, newPackageNo and quantityBase."
            }
          ]
        }
      ]
    },
    "errors": [
      {
        "code": "PreconditionFailed",
        "when": "The selected journal contains no lines.",
        "fix": "Select a batch with lines or a valid line subset."
      },
      {
        "code": "PermissionDenied",
        "when": "The caller lacks the item posting permission (Item Posting Gate) or write permission on the item journal.",
        "fix": "Ask an administrator for Item Posting Gate."
      },
      {
        "code": "InvalidParameter",
        "when": "The Physical Inventory domain is turned off for this company in Inventory Setup.",
        "fix": "Turn the domain on from the Inventory Setup page."
      },
      {
        "code": "BusinessCentralError",
        "error": "Business Central posting error text",
        "when": "The posting fails, for example because a line fails the item journal checks, or a selected line is not a valid physical inventory line. Nothing is posted.",
        "fix": "Run Inventory.PhysInventory.Check, correct the lines named in its answer and retry."
      },
      {
        "code": "BusinessCentralError",
        "error": "Unsupported journal parameter %1.",
        "when": "A key is sent that this type does not read.",
        "fix": "Remove the key; only the batch selectors and the declared parameters are accepted."
      },
      {
        "code": "BusinessCentralError",
        "error": "Identify one existing journal batch using templateName and batchName or subject TEMPLATE|BATCH or SystemId.",
        "when": "No batch is identified, the selectors name different batches, the subject is neither TEMPLATE|BATCH nor a SystemId, the batch does not exist, or its template is not a Phys. Inventory template or is recurring.",
        "fix": "Identify one existing batch of a non-recurring Phys. Inventory template with consistent selectors."
      },
      {
        "code": "BusinessCentralError",
        "error": "lineSystemIds must be a nonempty array of distinct SystemIds belonging to the identified journal batch.",
        "when": "lineSystemIds is not an array, is empty, repeats an id, or names a line outside the batch.",
        "fix": "Send distinct SystemIds of lines in the selected batch, or omit lineSystemIds."
      }
    ],
    "effect": {
      "effect": "irreversible",
      "changes": "Posts the selected lines of the Phys. Inventory journal batch through the standard item journal batch posting: item ledger entries, physical inventory ledger entries, value entries and an item register are created and the posted lines leave the journal. The posting commits with the answer; under Omit Commit the caller's transaction commits instead. It cannot be undone by a message type of this app.",
      "idempotent": false,
      "permissionSet": "the Bifrost \"Full Access\" permission set and Item Posting Gate",
      "writes": true,
      "posts": true,
      "rollback": false
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Inventory.PhysInventory.Check",
        "useInsteadWhen": "Use it first to list line problems without posting."
      },
      {
        "name": "Inventory.PhysInventory.PreviewPost",
        "useInsteadWhen": "Use it first to see the entries the posting would create."
      },
      {
        "name": "Inventory.PhysInventory.RecordCount",
        "useInsteadWhen": "Use it to change the counted quantities before posting."
      },
      {
        "name": "Inventory.PhysInventory.Calculate",
        "useInsteadWhen": "Use it to fill an empty batch with the expected stock before counting."
      }
    ],
    "workflow": {
      "steps": [
        {
          "messageType": "Inventory.PhysInventory.Check",
          "purpose": "Find line problems first."
        },
        {
          "messageType": "Inventory.PhysInventory.PreviewPost",
          "purpose": "See the entries the posting would create."
        },
        {
          "messageType": "Inventory.PhysInventory.Post",
          "purpose": "Post the count; the adjustments are written to the ledger."
        }
      ]
    },
    "examples": [
      {
        "title": "Post the whole batch DEFAULT",
        "request": {
          "type": "Inventory.PhysInventory.Post",
          "subject": "PHYS. INV.|DEFAULT"
        },
        "response": {
          "status": "Success",
          "templateName": "PHYS. INV.",
          "batchName": "DEFAULT",
          "postedLineCount": 1,
          "itemRegisterNo": 1250,
          "fromEntryNo": 8812,
          "toEntryNo": 8812,
          "fromPhysInventoryEntryNo": 410,
          "toPhysInventoryEntryNo": 410,
          "result": [
            {
              "systemId": "6f1c1d2e-0000-0000-0000-000000000001",
              "lineNo": 10000,
              "itemNo": "1000",
              "quantity": 2,
              "locationCode": "",
              "newLocationCode": "",
              "binCode": "",
              "newBinCode": "",
              "lotNo": "",
              "newLotNo": "",
              "serialNo": "",
              "newSerialNo": "",
              "packageNo": "",
              "newPackageNo": "",
              "tracking": []
            }
          ]
        }
      }
    ],
    "overview": "Posts the lines of one Phys. Inventory journal batch, or only the lines in lineSystemIds, and returns the item register and the entry number ranges. Posting is permanent and needs the item posting permission.",
    "notes": "Posting is permanent and commits: the posting commits with the answer, and under Omit Commit the caller's transaction commits instead. The commits inside Business Central's batch posting are held back, so a failure rolls back the whole posting. Under Omit Commit an error is raised to the caller instead of being answered with the error text. Without lineSystemIds every line of the batch is posted; with lineSystemIds only those lines (distinct SystemIds of lines in the batch). A batch without lines is refused with PreconditionFailed. Every selected line must have an item that is not blocked, be a physical inventory line, have the entry type Positive Adjmt. or Negative Adjmt., the value entry type Direct Cost and no item charge, and must pass the item journal checks; otherwise nothing is posted and the error text is answered with BusinessCentralError. The caller needs the item posting permission (Item Posting Gate) as well as write access to the journal; without it the call is refused with PermissionDenied. The Physical Inventory domain must be turned on in Inventory Setup (a missing setup row counts as on). fromPhysInventoryEntryNo and toPhysInventoryEntryNo are 0 when the posting created no physical inventory ledger entry. Use Inventory.PhysInventory.Check and Inventory.PhysInventory.PreviewPost first."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\nViðbætur (Foundation 28.0.8 eða nýrri) geta kallað á `Argument.SetErrorContext(Parameter, Expected, NextStep)` fyrir aðgerð sem gæti mistekist eftir gagnaskrif og síðan `Argument.ClearErrorContext()` eftir að hún tekst. Gefðu upp heiti færibreytu og þýddan texta, aldrei gildi úr beiðni, skráarinnihald, aðgangsupplýsingar eða kallstafla. Foundation skilar þessu samhengi með upprunalegu `BusinessCentralError` eftir afturköllun, einnig við ómeðhöndlaðar verkefnisvillur; `RespondWithLastError()` notar það líka. Viðmótið grípur ekki villur, staðfestir ekki gagnaskrif og breytir ekki færslumörkum. Haltu `Codeunit.Run` án skilagildis og láttu villur berast áfram þegar `OmitCommit` köll eru keðjuð; bættu aldrei við Boolean `Codeunit.Run` eða `TryFunction` sem skrifar gögn til að endurheimta samhengi. Samhengið er hreinsað milli skilaboða. Kallendur án samhengis halda óbreyttri uppbyggingu svars; þekktar læsingarvillur halda núverandi `Retryable` leiðbeiningum.\r\nSkilaboðagerð sem má aðeins keyra eftir einni leið (Foundation 28.0.9 eða nýrri) les `Argument.GetInvocationSource()`: `Queue` þegar verkraðari keyrir skilaboð sem biðraðarviðmótið setti í röð, `Task` fyrir verkviðmótið (`/tasks`), `Dispatcher` fyrir innra kall í gegnum `Dispatcher ori` (innbyggða MCP-verkfæraþjóninn, hreiðrað kall úr annarri skilaboðagerð) og `Direct` fyrir aðgerðina Keyra vinnslu á síðunni Skilaboð og allt sem ekki er skráð. Aðeins Foundation skráir gildið; gildi í beiðni, færibreytur, uppruni, efni og skrif í færibreytuna breyta því ekki. Hafnaðu öðrum leiðum með `PreconditionFailed` og `nextStep` sem nefnir leiðina sem á að nota.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Other platform errors, including uncaught queue-path errors, remain `BusinessCentralError`.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`. The `error` text may be translated; the code never is.\r\n"
}
